#!/bin/sh
set -eu

runner=$1
case "$runner" in /*) ;; *) runner="$PWD/$runner";; esac
scratch=$(mktemp -d)
trap 'rm -rf "$scratch"' EXIT
export OCPKG_CACHE="$scratch/cache"
cd "$scratch"
mkdir -p src a
printf 'let value = 17\n' > a/util.ml
printf 'val value : int\n' > a/util.mli
printf 'let next () = Util.value + 1\n' > a/more.ml
# The digest is generated by the compatible SHA-256 tree codec (same tree as
# wrapped_packages.sh).
a_tree=6f03b5233de5eb457bff61dcb0ae84abe7b627d1edda058436890d297415fc2e
cat > fixture.snap <<SNAP
schema 1
pkg alpha 1
  local a
  tree $a_tree
  wrapped Alpha
  file util.ml <= util.ml
  file util.mli <= util.mli
  file more.ml <= more.ml
SNAP
cat > ocpkg.mod <<'MOD'
module test-publish
entry src/main.ml
source src
snapshot fixture.snap
require (
  alpha 1
)
MOD
cat > src/main.ml <<'ML'
let () = Printf.printf "%d\n" (Alpha.More.next ())
ML

"$runner" tidy
"$runner" vendor --offline

"$runner" publish --into published
test -f published/alpha/libalpha.a
test -f published/alpha/libalpha.a.opt
test -f published/alpha/alpha.cmi
test -f published/alpha/alpha.exports
test -f published/alpha/private/alpha__Util.cmi
test -f published/alpha/private/alpha__More.cmi
test -f published/alpha/units
test -f published/alpha/ldflags
grep -q Alpha__Util published/alpha/units
grep -q '^Alpha$' published/alpha/units

# Re-publishing replaces the artifacts without error.
"$runner" publish --into published
test -f published/alpha/libalpha.a

# Publishing a selection requires the names to be in the lock.
"$runner" publish --into published2 alpha
test -f published2/alpha/libalpha.a
if "$runner" publish --into published3 beta > publish.out 2> publish.log; then
    echo 'unknown package was published' >&2
    exit 1
fi
grep -q 'unknown package: beta' publish.log

# -o selects the destination like build.
"$runner" publish -o published4
test -f published4/alpha/libalpha.a

echo 'package artifact publishing: PASS'
